--

CREATE FUNCTION dynamic.log_activity_log_person_handlers_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO activity_log_person_handler_history (
    master_id,
    person_id,
    action, alt_action, more_data,
    extra_log_type,
    user_id,
    created_at,
    updated_at,
    activity_log_person_handler_id)
  SELECT
    NEW.master_id,
    NEW.person_id,
    NEW.action, NEW.alt_action, NEW.more_data,
    NEW.extra_log_type,
    NEW.user_id,
    NEW.created_at,
    NEW.updated_at,
    NEW.id;
  RETURN NEW;
END;
$$;


