--
-- Name: al_person_handlers_from_al_person_handlers; Type: VIEW; Schema: dynamic; Owner: -
--

CREATE VIEW dynamic.al_person_handlers_from_al_person_handlers AS
 SELECT dest.id,
    dest.master_id,
    dest.person_id,
    dest.extra_log_type,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    dest.action,
    dest.alt_action,
    dest.more_data,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'dynamic.activity_log_person_handlers'::character varying AS from_table
   FROM (dynamic.activity_log_person_handlers dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.from_record_type)::text = 'ActivityLog::PersonHandler'::text) AND ((mr.to_record_type)::text = 'ActivityLog::PersonHandler'::text))));


