--
-- Name: batch_incentive_trackers_hci_updates; Type: VIEW; Schema: dynamic; Owner: -
--

CREATE VIEW dynamic.batch_incentive_trackers_hci_updates AS
 WITH redcaps AS (
         SELECT incentives_hci_gift_card_rcs.id,
            incentives_hci_gift_card_rcs.record_id,
            incentives_hci_gift_card_rcs.name,
            incentives_hci_gift_card_rcs.email,
            incentives_hci_gift_card_rcs.request_date,
            incentives_hci_gift_card_rcs.gift_card_request_complete,
            incentives_hci_gift_card_rcs.gift_card_request_timestamp,
            incentives_hci_gift_card_rcs.redcap_survey_identifier,
            incentives_hci_gift_card_rcs.request_method,
            incentives_hci_gift_card_rcs.has_rejected,
            incentives_hci_gift_card_rcs.gift_card_type,
            incentives_hci_gift_card_rcs.amount,
            incentives_hci_gift_card_rcs.paid_date,
            incentives_hci_gift_card_rcs.has_received,
            incentives_hci_gift_card_rcs.received_method,
            incentives_hci_gift_card_rcs.has_attempted_contact,
            incentives_hci_gift_card_rcs.attempted_contact_date,
            incentives_hci_gift_card_rcs.sent_by_user_id,
            incentives_hci_gift_card_rcs.notes,
            incentives_hci_gift_card_rcs.user_id,
            incentives_hci_gift_card_rcs.created_at,
            incentives_hci_gift_card_rcs.updated_at
           FROM redcap.incentives_hci_gift_card_rcs
          WHERE ((incentives_hci_gift_card_rcs.record_id)::integer >= 1240)
        ), emails AS (
         SELECT max(player_contacts.id) AS id,
            player_contacts.master_id,
            player_contacts.data
           FROM ml_app.player_contacts
          WHERE ((player_contacts.rec_type)::text = 'email'::text)
          GROUP BY player_contacts.master_id, player_contacts.data
        ), infos AS (
         SELECT max(player_infos.master_id) AS master_id,
            (((player_infos.first_name)::text || ' '::text) || (player_infos.last_name)::text) AS name
           FROM ml_app.player_infos
          GROUP BY player_infos.master_id, (((player_infos.first_name)::text || ' '::text) || (player_infos.last_name)::text)
        )
 SELECT i.id,
    m.id AS master_id,
    i.name,
    i.email,
    i.request_date,
    i.request_method,
    i.gift_card_type,
    i.amount,
    COALESCE(i.has_rejected, false) AS has_rejected,
    i.paid_date,
    i.has_received,
    i.received_method,
    i.has_attempted_contact,
    i.attempted_contact_date,
    i.sent_by_user_id,
    i.notes,
    m.msid,
        CASE
            WHEN (pc.master_id IS NULL) THEN 'no email match'::text
            ELSE NULL::text
        END AS email_match,
    i.record_id AS "redcap id",
    i.user_id
   FROM (((redcaps i
     LEFT JOIN emails pc ON ((lower((pc.data)::text) = lower((i.email)::text))))
     LEFT JOIN infos pi ON (((lower(pi.name) = lower((i.name)::text)) AND (pc.data IS NULL))))
     LEFT JOIN ml_app.masters m ON ((COALESCE(pc.master_id, pi.master_id) = m.id)))
  WHERE ((m.id IS NOT NULL) AND (((i.paid_date IS NOT NULL) AND (( SELECT t.id
           FROM ml_app.tracker_history t
          WHERE ((t.master_id = m.id) AND (t.protocol_event_id = 940) AND (t.item_id = i.id))) IS NULL)) OR ((i.paid_date IS NULL) AND (( SELECT t.id
           FROM ml_app.tracker_history t
          WHERE ((t.master_id = m.id) AND (t.protocol_event_id = 942) AND (t.item_id = i.id))) IS NULL)) OR (COALESCE(i.has_rejected, false) AND (( SELECT t.id
           FROM ml_app.tracker_history t
          WHERE ((t.master_id = m.id) AND (t.protocol_event_id = 941) AND (t.item_id = i.id))) IS NULL))));


