--
-- Name: nfs_store_containers_from_al_view_user_data_user_procs; Type: VIEW; Schema: dynamic; Owner: -
--

CREATE VIEW dynamic.nfs_store_containers_from_al_view_user_data_user_procs AS
 SELECT dest.id,
    dest.name,
    dest.user_id,
    dest.app_type_id,
    dest.nfs_store_container_id,
    dest.master_id,
    dest.created_at,
    dest.updated_at,
    dest.created_by_user_id,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'nfs_store_containers'::character varying AS from_table
   FROM (ml_app.nfs_store_containers dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.to_record_type)::text = 'NfsStore::Manage::Container'::text))));


