--
-- Name: scantrons; Type: TABLE; Schema: ml_app; Owner: -
--

CREATE TABLE ml_app.scantrons (
    id integer NOT NULL,
    master_id integer,
    scantron_id integer,
    user_id integer,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL
);


--
-- Name: scantrons_from_al_person_handlers; Type: VIEW; Schema: dynamic; Owner: -
--

CREATE VIEW dynamic.scantrons_from_al_person_handlers AS
 SELECT dest.id,
    dest.master_id,
    dest.scantron_id,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'scantrons'::character varying AS from_table
   FROM (ml_app.scantrons dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.to_record_type)::text = 'Scantron'::text))));


