--

COMMENT ON TABLE dynamic.test_app_uacs IS 'Dynamicmodel: Test 77';


--
-- Name: test_app_uacs_from_al_person_handlers; Type: VIEW; Schema: dynamic; Owner: -
--

CREATE VIEW dynamic.test_app_uacs_from_al_person_handlers AS
 SELECT dest.id,
    dest.master_id,
    dest.test1,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'dynamic.test_app_uacs'::character varying AS from_table
   FROM (dynamic.test_app_uacs dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.to_record_type)::text = 'DynamicModel::TestAppUac'::text))));


