-- Name: activity_logs; Type: TABLE; Schema: ml_app; Owner: -
--

CREATE TABLE ml_app.activity_logs (
    id integer NOT NULL,
    name character varying,
    item_type character varying,
    rec_type character varying,
    admin_id integer,
    disabled boolean,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    action_when_attribute character varying,
    field_list character varying,
    blank_log_field_list character varying,
    blank_log_name character varying,
    extra_log_types character varying,
    hide_item_list_panel boolean,
    main_log_name character varying,
    process_name character varying,
    table_name character varying,
    category character varying,
    schema_name character varying
);


--
-- Name: view_activity_labels; Type: VIEW; Schema: dynamic; Owner: -
--

CREATE VIEW dynamic.view_activity_labels AS
 SELECT id AS activity_log_id,
    disabled,
    table_name,
    matches[1] AS extra_log_type,
    matches[2] AS label
   FROM ( SELECT activity_logs.id,
            activity_logs.disabled,
            activity_logs.table_name,
            regexp_matches((activity_logs.extra_log_types)::text, '[\\A\r\n]+([a-z_]+):[ &a-zA-Z_]*[\r\n]+(?:[\s#]+(?:<<:|#)[^\r\n]+[\r\n]+)*[\s]+label: ([^\r\n]+)'::text, 'g'::text) AS matches
           FROM ml_app.activity_logs) t
  ORDER BY id;


--
-- Name: VIEW view_activity_labels; Type: COMMENT; Schema: dynamic; Owner: -
--

COMMENT ON VIEW dynamic.view_activity_labels IS 'Dynamicmodel: Activity Lables';


