--
-- Name: next_msid_values; Type: VIEW; Schema: ref_data; Owner: -
--

CREATE VIEW ref_data.next_msid_values AS
 SELECT (max(msid) + 1) AS msid
   FROM ml_app.masters;


--
-- Name: view_pfrpa_cis_recs; Type: VIEW; Schema: dynamic; Owner: -
--

CREATE VIEW dynamic.view_pfrpa_cis_recs AS
 WITH live_merge AS (
         SELECT 1 AS id,
            10003 AS msid,
            2 AS football_players_health_study_questionnaire_1_complete
        ), biodata_participants AS (
         SELECT 1 AS id,
            10003 AS master_id
        ), latest_tracker AS (
         SELECT max(tracker_history.id) AS max_id,
            tracker_history.master_id
           FROM ml_app.tracker_history
          WHERE (((tracker_history.sub_process_id = 57) AND ((tracker_history.notes)::text ~~ 'Opted in to study by PFRPA CIS (%)'::text)) OR ((tracker_history.sub_process_id = 242) AND ((tracker_history.notes)::text ~~ 'Opted in to HBI by PFRPA CIS (%)'::text)) OR (tracker_history.protocol_event_id = ANY (ARRAY[35, 36, 833, 800])))
          GROUP BY tracker_history.master_id
        ), latest_tracker_event AS (
         SELECT DISTINCT th.id,
            th.master_id,
            th.protocol_id,
            th.tracker_id,
            th.event_date,
            th.user_id,
            th.notes,
            th.created_at,
            th.updated_at,
            th.sub_process_id,
            th.protocol_event_id,
            th.item_id,
            th.item_type
           FROM (ml_app.tracker_history th
             JOIN latest_tracker lt_1 ON ((th.id = lt_1.max_id)))
        )
 SELECT DISTINCT cis.id AS cis_id,
        CASE
            WHEN ((cis.provide_blood_smaple)::text = '0'::text) THEN 'yes'::text
            ELSE 'no'::text
        END AS hbi_enroll,
    pc.id AS player_contact_id,
    pi.id AS player_info_id,
    a.id AS address_id,
    COALESCE(m.id, '-1'::integer) AS master_id,
    m.msid,
    rc.msid AS q1_rcsi,
    (bp.id IS NOT NULL) AS biodata_participant,
    lt.sub_process_id,
    lt.protocol_event_id,
    next_msid.msid AS next_msid,
    cis.id,
    cis.record_id,
    cis.first_name,
    cis.last_name,
    cis.nickname,
    cis.cis_yob,
    cis.email,
    cis.st_address,
    cis.st_address_cont,
    cis.city,
    cis.state,
    cis.zip_code,
    cis.cell_number,
    cis.other_number,
    cis.nfl_contract,
    cis.current_former_player,
    cis.provide_blood_smaple,
    cis.not_interested_sample___0,
    cis.not_interested_sample___1,
    cis.not_interested_sample___2,
    cis.not_interested_sample___3,
    cis.not_interested_sample___4,
    cis.not_interested_sample___5,
    cis.explain,
    cis.personal_results,
    cis.other_share,
    cis.football_players_health_study_pro_football_retired_complete,
    cis.football_players_health_study_pro_football_retired_timestamp,
    cis.redcap_survey_identifier,
    cis.user_id,
    cis.created_at,
    cis.updated_at
   FROM (((((((((redcap.pfrpa_cis_rcs cis
     LEFT JOIN ml_app.tracker_history opt_in ON (((opt_in.sub_process_id = 57) AND (opt_in.item_id = cis.id) AND ((opt_in.item_type)::text = 'dynamic_model__pfrpa_cis_rc'::text))))
     LEFT JOIN ml_app.player_contacts pc ON (((TRIM(BOTH FROM lower((cis.email)::text)) = (pc.data)::text) AND ((pc.rec_type)::text = 'email'::text))))
     LEFT JOIN ml_app.player_infos pi ON (((TRIM(BOTH FROM lower((cis.first_name)::text)) = lower((pi.first_name)::text)) AND (TRIM(BOTH FROM lower((cis.last_name)::text)) = lower((pi.last_name)::text)))))
     LEFT JOIN ml_app.addresses a ON (((TRIM(BOTH FROM cis.zip_code) = (a.zip)::text) AND (pi.master_id = a.master_id))))
     LEFT JOIN ml_app.masters m ON ((COALESCE(opt_in.master_id, a.master_id, pc.master_id) = m.id)))
     LEFT JOIN live_merge rc ON (((rc.msid = m.msid) AND (rc.football_players_health_study_questionnaire_1_complete = 2))))
     LEFT JOIN biodata_participants bp ON ((m.id = bp.master_id)))
     LEFT JOIN latest_tracker_event lt ON ((m.id = lt.master_id)))
     LEFT JOIN ref_data.next_msid_values next_msid ON ((next_msid.msid IS NOT NULL)))
  WHERE (NOT ((rc.msid IS NOT NULL) AND (((cis.provide_blood_smaple)::text = '1'::text) OR (bp.id IS NOT NULL))));


--
-- Name: VIEW view_pfrpa_cis_recs; Type: COMMENT; Schema: dynamic; Owner: -
--

COMMENT ON VIEW dynamic.view_pfrpa_cis_recs IS 'Dynamicmodel: Pfrpa Registration Events';


