    select_problem_type character varying,
    event_occurred_when date,
    event_discovered_when date,
    select_severity character varying,
    select_location character varying,
    select_expectedness character varying,
    select_relatedness character varying,
    event_description character varying,
    corrective_action_description character varying,
    user_id integer,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    ipa_adverse_event_id integer
);


--
-- Name: COLUMN ipa_adverse_event_history.select_problem_type; Type: COMMENT; Schema: ipa_ops; Owner: -
--

COMMENT ON COLUMN ipa_ops.ipa_adverse_event_history.select_problem_type IS 'Select type of event:
<b>adverse event</b> - caused potential harm to subject <span class="glyphicon glyphicon-question-sign" data-toggle="popover" data-trigger="click hover" data-content="Adverse event means any untoward or unfavorable medical occurrence in a human subject, including any abnormal sign (for example, abnormal physical exam or laboratory finding), symptom, or disease, temporally associated with the subject’s participation in the research, whether or not considered related to the subject’s participation in the research (modified from the definition of adverse events in the 1996 International Conference on Harmonization E-6 Guidelines for Good Clinical Practice)." data-original-title="" title=""></span>
<b>other event</b> - other unanticipated problem that may increase risk of harm';


--
-- Name: COLUMN ipa_adverse_event_history.event_occurred_when; Type: COMMENT; Schema: ipa_ops; Owner: -
--

COMMENT ON COLUMN ipa_ops.ipa_adverse_event_history.event_occurred_when IS 'Date event occurred';


--
-- Name: COLUMN ipa_adverse_event_history.event_discovered_when; Type: COMMENT; Schema: ipa_ops; Owner: -
--

COMMENT ON COLUMN ipa_ops.ipa_adverse_event_history.event_discovered_when IS 'Date event was discovered';


--
-- Name: COLUMN ipa_adverse_event_history.select_severity; Type: COMMENT; Schema: ipa_ops; Owner: -
--

COMMENT ON COLUMN ipa_ops.ipa_adverse_event_history.select_severity IS 'Select severity of the event';


--
-- Name: COLUMN ipa_adverse_event_history.select_location; Type: COMMENT; Schema: ipa_ops; Owner: -
--

COMMENT ON COLUMN ipa_ops.ipa_adverse_event_history.select_location IS 'Select where the event was experienced.
<b>internal</b> - sites that are relying on FPHS IRB for review of research
<b>external</b> - sites not relying on FPHS IRB for review of research';


--
-- Name: COLUMN ipa_adverse_event_history.select_expectedness; Type: COMMENT; Schema: ipa_ops; Owner: -
--

COMMENT ON COLUMN ipa_ops.ipa_adverse_event_history.select_expectedness IS 'Was this event expected? If unsure, leave blank.
An event may be considered to be <b>expected</b> if it is described in the consent forms.';


--
-- Name: COLUMN ipa_adverse_event_history.select_relatedness; Type: COMMENT; Schema: ipa_ops; Owner: -
--

COMMENT ON COLUMN ipa_ops.ipa_adverse_event_history.select_relatedness IS 'Select whether the event is related to the assessment
<b>related</b> - the event highly likely to be related to participation
<b>possibly related</b> - the event is more likely than not related to participation
<b>unrelated</b> - the event is highly unlikely to be related to participation';


--
-- Name: COLUMN ipa_adverse_event_history.event_description; Type: COMMENT; Schema: ipa_ops; Owner: -
--

COMMENT ON COLUMN ipa_ops.ipa_adverse_event_history.event_description IS 'Describe in detail the event that occurred. If necessary, upload additional files after saving this form.';


