--
-- Name: al_org_alt_username_setups_from_al_org_alt_username_setups; Type: VIEW; Schema: organization; Owner: -
--

CREATE VIEW organization.al_org_alt_username_setups_from_al_org_alt_username_setups AS
 SELECT dest.id,
    dest.master_id,
    dest.org_alt_username_id,
    dest.orig_request_date,
    dest.select_alt_username,
    dest.user_first_name,
    dest.user_last_name,
    dest.primary_email,
    dest.created_by_user_id,
    dest.status,
    dest.disabled,
    dest.extra_log_type,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'organization.activity_log_org_alt_username_setups'::character varying AS from_table
   FROM (organization.activity_log_org_alt_username_setups dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.from_record_type)::text = 'ActivityLog::OrgAltUsernameSetup'::text) AND ((mr.to_record_type)::text = 'ActivityLog::OrgAltUsernameSetup'::text))));


--
-- Name: nfs_store_containers_from_al_org_alt_username_setups; Type: VIEW; Schema: organization; Owner: -
--

CREATE VIEW organization.nfs_store_containers_from_al_org_alt_username_setups AS
 SELECT dest.id,
    dest.name,
    dest.user_id,
    dest.app_type_id,
    dest.nfs_store_container_id,
    dest.master_id,
    dest.created_at,
    dest.updated_at,
    dest.created_by_user_id,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'nfs_store_containers'::character varying AS from_table
   FROM (ml_app.nfs_store_containers dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.from_record_type)::text = 'ActivityLog::OrgAltUsernameSetup'::text) AND ((mr.to_record_type)::text = 'NfsStore::Manage::Container'::text))));


