-- Name: al_pitt_bhi_assignment_discussions_from_al_pitt_bhi_assignment_; Type: VIEW; Schema: pitt_bhi; Owner: -
--

CREATE VIEW pitt_bhi.al_pitt_bhi_assignment_discussions_from_al_pitt_bhi_assignment_ AS
 SELECT dest.id,
    dest.master_id,
    dest.pitt_bhi_assignment_id,
    dest.notes,
    dest.tag_select_contact_role,
    dest.prev_activity_type,
    dest.extra_log_type,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'activity_log_pitt_bhi_assignment_discussions'::character varying AS from_table
   FROM (pitt_bhi.activity_log_pitt_bhi_assignment_discussions dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.from_record_type)::text = 'ActivityLog::PittBhiAssignmentDiscussion'::text) AND ((mr.to_record_type)::text = 'ActivityLog::PittBhiAssignmentDiscussion'::text))));


