     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.from_record_type)::text = 'ActivityLog::PittBhiAssignment'::text) AND ((mr.to_record_type)::text = 'NfsStore::Manage::Container'::text))));


