--
-- Name: pitt_bhi_appointments_from_al_pitt_bhi_assignments; Type: VIEW; Schema: pitt_bhi; Owner: -
--

CREATE VIEW pitt_bhi.pitt_bhi_appointments_from_al_pitt_bhi_assignments AS
 SELECT dest.id,
    dest.visit_start_date,
    dest.visit_end_date,
    dest.select_status,
    dest.notes,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    dest.master_id,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'pitt_bhi.pitt_bhi_appointments'::character varying AS from_table
   FROM (pitt_bhi.pitt_bhi_appointments dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.to_record_type)::text = 'DynamicModel::PittBhiAppointment'::text))));


