 SELECT dest.id,
    dest.contact_info_notes,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    dest.consent_to_pass_info_to_pitt_yes_no,
    dest.consent_to_pass_info_to_pitt_2_yes_no,
    dest.master_id,
    dest.not_interested_notes,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'pitt_bhi.pitt_bhi_ps_eligibles'::character varying AS from_table
   FROM (pitt_bhi.pitt_bhi_ps_eligibles dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.from_record_type)::text = 'ActivityLog::PittBhiAssignmentPhoneScreen'::text) AND ((mr.to_record_type)::text = 'DynamicModel::PittBhiPsEligible'::text))));


