--
-- Name: TABLE rc_q2_demos; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON TABLE redcap.rc_q2_demos IS 'Dynamicmodel: Rc Q2 Demo';


--
-- Name: COLUMN rc_q2_demos.record_id; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.record_id IS 'Record ID';


--
-- Name: COLUMN rc_q2_demos.dob; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.dob IS 'Date of birth:';


--
-- Name: COLUMN rc_q2_demos.current_weight; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.current_weight IS 'What is your current weight?';


--
-- Name: COLUMN rc_q2_demos.domestic_status; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.domestic_status IS 'What is your current marital status?';


--
-- Name: COLUMN rc_q2_demos.living_situation; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.living_situation IS 'How would you describe your current living situation?';


--
-- Name: COLUMN rc_q2_demos.current_employment; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.current_employment IS 'Are you currently employed?';


--
-- Name: COLUMN rc_q2_demos.student_looking; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.student_looking IS 'If you are unemployed, are you currently a student or looking for work?';


--
-- Name: COLUMN rc_q2_demos.current_fbjob; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.current_fbjob IS 'If you work in football, please provide additional information:';


--
-- Name: COLUMN rc_q2_demos.current_fbjob_oth; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.current_fbjob_oth IS 'If "Other", please specify:';


--
-- Name: COLUMN rc_q2_demos.job_industry; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.job_industry IS 'Specify your employment industry. (If you are retired, specify the last industry in
which you were employed.)';


--
-- Name: COLUMN rc_q2_demos.job_title; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.job_title IS 'Select the option that best represents your job title. (If you are retired,
indicate the title of your last job)';


--
-- Name: COLUMN rc_q2_demos.job_title_entry; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.job_title_entry IS 'Enter your job title: (If you are retired, enter the title of your last
job)';


--
-- Name: COLUMN rc_q2_demos.smoke; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.smoke IS 'Have you ever smoked cigarettes?  (Smoked at least 100 cigarettes in your lifetime. Do not include pipe and cigars)';


--
-- Name: COLUMN rc_q2_demos.smoketime___pnfl; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.smoketime___pnfl IS 'Before playing in the NFL';


--
-- Name: COLUMN rc_q2_demos.smoketime___dnfl; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.smoketime___dnfl IS 'While playing in the NFL';


--
-- Name: COLUMN rc_q2_demos.smoketime___anfl; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.smoketime___anfl IS 'After playing in the NFL';


--
-- Name: COLUMN rc_q2_demos.smoke_start; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.smoke_start IS 'How old were you when you started smoking?';


--
-- Name: COLUMN rc_q2_demos.smoke_stop; Type: COMMENT; Schema: redcap; Owner: -
--

COMMENT ON COLUMN redcap.rc_q2_demos.smoke_stop IS 'How old were you when you stopped smoking?';


--
