--
-- Name: al_data_variable_package_reviews_from_al_data_variable_package_; Type: VIEW; Schema: study_info; Owner: -
--

CREATE VIEW study_info.al_data_variable_package_reviews_from_al_data_variable_package_ AS
 SELECT dest.id,
    dest.master_id,
    dest.data_variable_package_id,
    dest.assigned_to_user,
    dest.package_id,
    dest.status,
    dest.disabled,
    dest.extra_log_type,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    dest.db_table_name,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'study_info.activity_log_data_variable_package_reviews'::character varying AS from_table
   FROM (study_info.activity_log_data_variable_package_reviews dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.from_record_type)::text = 'ActivityLog::DataVariablePackageReview'::text) AND ((mr.to_record_type)::text = 'ActivityLog::DataVariablePackageReview'::text))));


--
-- Name: al_study_info_parts_from_al_study_info_parts; Type: VIEW; Schema: study_info; Owner: -
--

CREATE VIEW study_info.al_study_info_parts_from_al_study_info_parts AS
 SELECT dest.id,
    dest.master_id,
    dest.study_info_part_id,
    dest.title,
    dest.description,
    dest.extra_log_type,
    dest.user_id,
    dest.created_at,
    dest.updated_at,
    dest.default_layout,
    dest.slug,
    dest.notes,
    dest.tag_select_allow_roles_access,
    dest.position_number,
    dest.extra_classes,
    dest.footer,
    dest.disabled,
    dest.block_width,
    mr.from_record_master_id,
    mr.from_record_type,
    mr.from_record_id,
    mr.id AS model_reference_id,
    'study_info.activity_log_study_info_parts'::character varying AS from_table
   FROM (study_info.activity_log_study_info_parts dest
     JOIN ml_app.model_references mr ON (((dest.id = mr.to_record_id) AND (dest.master_id = mr.to_record_master_id) AND (NOT COALESCE(mr.disabled, false)) AND ((mr.from_record_type)::text = 'ActivityLog::StudyInfoPart'::text) AND ((mr.to_record_type)::text = 'ActivityLog::StudyInfoPart'::text))));


--
-- Name: batch_missing_file_containers; Type: VIEW; Schema: study_info; Owner: -
--

CREATE VIEW study_info.batch_missing_file_containers AS
 SELECT umn.id,
    umn.for_user_id,
    umn.os_uname,
    al.id AS al_id,
    COALESCE(al.master_id, ('-1'::integer)::bigint) AS master_id,
    al.created_by_user_id,
    nfs.id AS container_id,
    nfs.created_by_user_id AS nfs_created_by_user_id
   FROM ((dynamic.user_map_names umn
     LEFT JOIN dynamic.activity_log_view_user_data_user_procs al ON (((al.created_by_user_id = umn.for_user_id) AND ((al.extra_log_type)::text = 'profile_files'::text))))
     LEFT JOIN dynamic.nfs_store_containers_from_al_view_user_data_user_procs nfs ON (((al.id = nfs.from_record_id) AND (al.master_id = nfs.from_record_master_id) AND ((nfs.from_record_type)::text = 'ActivityLog::ViewUserDataUserProc'::text))))
  WHERE ((NOT COALESCE(umn.disabled, false)) AND (((al.id IS NULL) AND (umn.for_user_id IS NOT NULL)) OR (nfs.created_by_user_id <> al.created_by_user_id)));


